new='''  const ORDERS_PAGE_SIZE = 20;

  app.get("/orders", async (req, res) => {
    // The cursor is the id of the last order on the previous page (ids grow with creation time).
    let before: number | null = null;
    if (req.query.cursor !== undefined) {
      const raw = req.query.cursor;
      if (typeof raw !== "string" || !/^[1-9]\\d{0,9}$/.test(raw) || Number(raw) > 2147483647) {
        return sendError(res, 400, "invalid_cursor", "Invalid cursor");
      }
      before = Number(raw);
    }
    const { rows } = await pool.query(
      `select id, status, total_cents, created_at from orders
       where user_id = $1 and ($2::int is null or id < $2)
       order by id desc limit $3`,
      [res.locals.user.id, before, ORDERS_PAGE_SIZE + 1],
    );
    const hasMore = rows.length > ORDERS_PAGE_SIZE;
    const orders = hasMore ? rows.slice(0, ORDERS_PAGE_SIZE) : rows;
    res.json({ orders, nextCursor: hasMore ? String(orders[orders.length - 1].id) : null });
  });

'''
